<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'; import { Plus, Search, Refresh, View, EditPen, Delete, OfficeBuilding } from '@element-plus/icons-vue'; import { adminApi, type EnterpriseQuery } from '@/api/admin'; import type { EnterpriseDetail, EnterpriseForm, EnterpriseListItem } from '@/types/domain'; import { useDictionaryStore } from '@/stores/dictionary'; import PageHeader from '@/components/PageHeader.vue'; import FilterBar from '@/components/FilterBar.vue'; import PaginationBar from '@/components/PaginationBar.vue'; import StatusTag from '@/components/StatusTag.vue'; import EmptyState from '@/components/EmptyState.vue'
const dict = useDictionaryStore(); const loading = ref(false); const dialogVisible = ref(false); const detailVisible = ref(false); const editingId = ref<string>(); const detail = ref<EnterpriseDetail>(); const formRef = ref<FormInstance>(); const rows = ref<EnterpriseListItem[]>([]); const total = ref(0)
const query = reactive<EnterpriseQuery>({ current: 1, size: 10, enterpriseName: '', creditCode: '', provinceCode: '', cityCode: '', enterpriseType: undefined, status: undefined }); const form = reactive<EnterpriseForm>({ enterpriseName: '', loginName: '', creditCode: '', enterpriseType: 1, password: '', legalPerson: '', contactPerson: '', contactPhone: '', provinceCode: '', cityCode: '', address: '', status: 1 })
const provinces = dict.provinces; const cities = ref<{ regionCode: string; regionName: string }[]>([]); const typeOptions = [{ value: 1, label: '捕捞 / 养殖' }, { value: 2, label: '冷冻加工' }, { value: 3, label: '批发流通' }, { value: 4, label: '零售终端' }]; const rules: FormRules = { enterpriseName: [{ required: true, message: '请输入企业名称', trigger: 'blur' }], loginName: [{ required: true, message: '请输入登录账号', trigger: 'blur' }], creditCode: [{ required: true, message: '请输入统一信用代码', trigger: 'blur' }], enterpriseType: [{ required: true, message: '请选择企业类型', trigger: 'change' }], provinceCode: [{ required: true, message: '请选择省份', trigger: 'change' }], cityCode: [{ required: true, message: '请选择城市', trigger: 'change' }] }
async function load() { loading.value = true; try { const result = await adminApi.enterprises(query); rows.value = result.records; total.value = result.total } catch (error) { ElMessage.error(error instanceof Error ? error.message : '企业列表加载失败') } finally { loading.value = false } }
async function changeProvince(code: string, target = form) { const result = code ? await dict.loadCities(code) : []; if (target === form) cities.value = result; else query.cityCode = '' }
function resetForm() { Object.assign(form, { enterpriseName: '', loginName: '', creditCode: '', enterpriseType: 1, password: '', legalPerson: '', contactPerson: '', contactPhone: '', provinceCode: '', cityCode: '', address: '', status: 1 }); editingId.value = undefined; cities.value = [] }
function openCreate() { resetForm(); dialogVisible.value = true }
async function openEdit(row: EnterpriseListItem) { const data = await adminApi.enterpriseDetail(row.id); Object.assign(form, data); editingId.value = row.id; cities.value = await dict.loadCities(form.provinceCode); dialogVisible.value = true }
async function openDetail(row: EnterpriseListItem) { detail.value = await adminApi.enterpriseDetail(row.id); detailVisible.value = true }
async function submit() { await formRef.value?.validate(); try { if (editingId.value) await adminApi.updateEnterprise(editingId.value, form); else await adminApi.createEnterprise(form); ElMessage.success(editingId.value ? '企业资料已更新' : '企业已创建'); dialogVisible.value = false; load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '保存失败') } }
async function remove(row: EnterpriseListItem) { await ElMessageBox.confirm(`确定删除「${row.enterpriseName}」吗？删除后不可恢复。`, '删除企业', { type: 'warning', confirmButtonText: '确认删除', cancelButtonText: '取消' }); try { await adminApi.deleteEnterprise(row.id); ElMessage.success('企业已删除'); load() } catch (error) { ElMessage.error(error instanceof Error ? error.message : '删除失败') } }
onMounted(async () => { await dict.loadProvinces(); load() })
</script>
<template><div class="enterprise-list-view"><PageHeader eyebrow="NODE NETWORK" title="节点企业" description="维护冷链网络中的企业注册信息"><template #default><el-button type="primary" :icon="Plus" @click="openCreate">新增企业</el-button></template></PageHeader><FilterBar><el-input v-model="query.enterpriseName" clearable placeholder="企业名称" style="width: 190px" @keyup.enter="query.current = 1; load()" /><el-input v-model="query.creditCode" clearable placeholder="统一信用代码" style="width: 190px" @keyup.enter="query.current = 1; load()" /><el-select v-model="query.enterpriseType" clearable placeholder="企业类型" style="width: 150px"><el-option v-for="option in typeOptions" :key="option.value" :label="option.label" :value="option.value" /></el-select><el-select v-model="query.status" clearable placeholder="状态" style="width: 130px"><el-option label="正常" :value="1" /><el-option label="停用" :value="0" /></el-select><template #actions><el-button :icon="Search" type="primary" @click="query.current = 1; load()">查询</el-button><el-button :icon="Refresh" @click="Object.assign(query, { enterpriseName: '', creditCode: '', enterpriseType: undefined, status: undefined, current: 1 }); load()">重置</el-button></template></FilterBar><section class="data-panel enterprise-table-panel"><div class="data-panel__head"><div><strong>企业名录</strong><span>共 {{ total }} 家企业</span></div><span class="table-caption">最后同步：刚刚</span></div><el-table v-loading="loading" :data="rows" row-key="id" min-width="980"><el-table-column label="企业" min-width="230"><template #default="{ row }"><div class="entity-cell"><span class="entity-cell__avatar"><el-icon><OfficeBuilding /></el-icon></span><div><strong>{{ row.enterpriseName }}</strong><small>{{ row.enterpriseCode }}</small></div></div></template></el-table-column><el-table-column prop="enterpriseTypeName" label="类型" width="125" /><el-table-column label="所在地区" min-width="170"><template #default="{ row }">{{ row.provinceName }} · {{ row.cityName }}</template></el-table-column><el-table-column prop="contactPerson" label="联系人" width="105" /><el-table-column prop="contactPhone" label="联系电话" width="140" /><el-table-column label="状态" width="95"><template #default="{ row }"><StatusTag :label="row.statusName" :tone="row.status === 1 ? 'success' : 'danger'" /></template></el-table-column><el-table-column label="操作" fixed="right" width="160"><template #default="{ row }"><el-button link type="primary" :icon="View" @click="openDetail(row)">详情</el-button><el-button link :icon="EditPen" @click="openEdit(row)">编辑</el-button><el-button link type="danger" :icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column><template #empty><EmptyState title="暂无节点企业" description="创建第一家企业，开始搭建冷链网络" /></template></el-table><PaginationBar :total="total" :page="query.current || 1" :size="query.size || 10" @change="(page) => { query.current = page; load() }" @update:size="(size) => { query.size = size; query.current = 1; load() }" /></section><el-dialog v-model="dialogVisible" :title="editingId ? '编辑企业' : '新增企业'" width="720px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="企业名称" prop="enterpriseName"><el-input v-model="form.enterpriseName" placeholder="请输入企业全称" /></el-form-item><el-form-item label="登录账号" prop="loginName"><el-input v-model="form.loginName" placeholder="用于企业端登录" :disabled="Boolean(editingId)" /></el-form-item><el-form-item label="统一信用代码" prop="creditCode"><el-input v-model="form.creditCode" placeholder="请输入统一社会信用代码" /></el-form-item><el-form-item label="企业类型" prop="enterpriseType"><el-select v-model="form.enterpriseType" style="width: 100%"><el-option v-for="option in typeOptions" :key="option.value" :label="option.label" :value="option.value" /></el-select></el-form-item><el-form-item v-if="!editingId" label="初始密码"><el-input v-model="form.password" type="password" show-password placeholder="留空使用默认密码 123456" /></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactPerson" /></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone" /></el-form-item><el-form-item label="法定代表人"><el-input v-model="form.legalPerson" /></el-form-item><el-form-item label="省份" prop="provinceCode"><el-select v-model="form.provinceCode" filterable style="width: 100%" @change="(value) => changeProvince(value)"><el-option v-for="item in provinces" :key="item.regionCode" :label="item.regionName" :value="item.regionCode" /></el-select></el-form-item><el-form-item label="城市" prop="cityCode"><el-select v-model="form.cityCode" filterable style="width: 100%"><el-option v-for="item in cities" :key="item.regionCode" :label="item.regionName" :value="item.regionCode" /></el-select></el-form-item><el-form-item class="form-grid__wide" label="详细地址"><el-input v-model="form.address" /></el-form-item></div></el-form><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" @click="submit">保存企业</el-button></template></el-dialog><el-drawer v-model="detailVisible" title="企业详情" size="520px"><template v-if="detail"><div class="detail-hero"><span class="detail-hero__avatar"><el-icon><OfficeBuilding /></el-icon></span><div><h3>{{ detail.enterpriseName }}</h3><p>{{ detail.enterpriseTypeName }} · {{ detail.enterpriseCode }}</p></div></div><div class="detail-list"><div><span>统一信用代码</span><strong>{{ detail.creditCode }}</strong></div><div><span>所在地区</span><strong>{{ detail.provinceName }} · {{ detail.cityName }}</strong></div><div><span>联系人</span><strong>{{ detail.contactPerson || '-' }} {{ detail.contactPhone || '' }}</strong></div><div><span>注册地址</span><strong>{{ detail.address || '-' }}</strong></div><div><span>注册时间</span><strong>{{ detail.registerTime || '-' }}</strong></div></div></template></el-drawer></div></template>
